333|    const active = await readActiveSnapshot(store);
334|    if (active === null) throw new Error('Download an offline copy before creating Entries offline');
335|    if (await store.readMeta(ENTRY_CREATE_CAPABILITY_KEY) !== '1') {
336|      throw new Error('This offline copy has not enabled offline Entry creation; update it while online');
337|    }
338|    const title = input.title.trim();
339|    const type = input.type.trim();
340|    if (title.length === 0 || type.length === 0) throw new Error('Title and Gallery are required');
341|    if (!active.snapshot.payload.entries.some((entry) => entry.type === type)) {
342|      throw new Error('Offline creation can only use an existing Gallery from this offline copy');
343|    }
344|    const files = [
345|      ...(input.coverFile === null ? [] : [{ kind: 'cover' as const, file: input.coverFile }]),
346|      ...(input.previewFile === null ? [] : [{ kind: 'preview' as const, file: input.previewFile }]),
