358|    } catch (cause) {
359|      if (cause instanceof Error && cause.message.startsWith('Not enough browser storage')) throw cause;
360|      // Storage estimation is advisory and is absent on some PWA engines. The
361|      // multi-store IndexedDB transaction remains the durability boundary.
362|    }
363|    const entityUid = randomUUID();
