365|      clientId,
366|      libraryId: active.snapshot.header.libraryId,
367|      syncEpoch: active.snapshot.header.syncEpoch,
368|      entityKind: 'entry',
369|      entityUid,
370|      operationKind: 'entry.create',
371|      baseVersion: 0,
372|      baseValues: {},
373|      payload: {
374|        title,
375|        type,
376|        uploadDate: input.uploadDate,
377|        pageCount: input.pageCount,
378|        ratings: [...input.ratings].sort((left, right) => left.slotId - right.slotId),
379|        viewLater: input.viewLater,
