415|  async function replayPendingOperations(): Promise<void> {
416|    if (replayPromise !== null) return replayPromise;
417|    replayPromise = (async () => {
418|      if (!hasOutbox(store) || online.replaySyncOperation === undefined) return;
419|      const operations = await store.list();
420|      const mediaBeforeReplay = hasMediaOutbox(store) ? await store.listMedia() : [];
421|      await setReplayStateFromStore();
422|      if (operations.length === 0 && mediaBeforeReplay.length === 0) return;
423|      const activeBeforeReplay = await readActiveSnapshot(store);
424|      const appliedOperations: SyncReplayOperation[] = [];
425|      const appliedMedia: StagedMediaUpload[] = [];
426|      let maxAppliedServerSeq = -1;
427|      const blockedEntities = new Set<string>();
428|      let replayError: string | null = null;
429|      let attemptedOpId: string | null = null;
430|      let attemptedUploadId: string | null = null;
431|      try {
432|        for (const stored of operations) {
433|          const entityKey = `${stored.entityKind}:${stored.entityUid}`;
434|          if (stored.status !== 'pending') {
435|            blockedEntities.add(entityKey);
436|            replayError ??= stored.lastError;
437|            continue;
438|          }
439|          if (blockedEntities.has(entityKey)) continue;
440|          let operation: SyncReplayOperation;
441|          try {
442|            operation = transportOperation(stored);
443|          } catch {
444|            // An envelope this build can no longer express (for example one queued
445|            // by another app version) must neither be sent nor silently dropped,
446|            // and it must not stop unrelated Entries from syncing.
447|            replayError = 'Invalid offline operation: this version cannot send it';
448|            await store.update(stored.opId, { status: 'failed', lastError: replayError });
449|            blockedEntities.add(entityKey);
450|            continue;
451|          }
452|          attemptedOpId = stored.opId;
453|          await store.update(stored.opId, {
454|            lastAttemptAt: new Date().toISOString(),
455|            lastError: null,
456|          });
457|          const result = await online.replaySyncOperation(operation);
458|          if (result.status === 'applied') {
459|            appliedOperations.push(operation);
460|            maxAppliedServerSeq = Math.max(maxAppliedServerSeq, result.serverSeq);
461|            attemptedOpId = null;
462|            continue;
463|          }
464|          if (result.status === 'conflict') {
465|            replayError = 'An offline edit conflicts with a newer server value';
466|            await store.update(stored.opId, { status: 'conflict', lastError: replayError });
467|          } else if (result.status === 'resnapshot-required') {
468|            replayError = 'The library changed and the offline edit needs review';
469|            await store.update(stored.opId, { status: 'conflict', lastError: replayError });
470|          } else {
471|            replayError = result.detail;
472|            await store.update(stored.opId, { status: 'failed', lastError: replayError });
473|          }
474|          blockedEntities.add(entityKey);
475|          attemptedOpId = null;
476|        }
477|
478|        if (hasMediaOutbox(store) && online.uploadSyncMedia !== undefined) {
479|          const readyEntryUids = new Set(
480|            activeBeforeReplay?.snapshot.payload.entries.map((entry) => entry.syncUid) ?? [],
481|          );
