265|      if (!isOfflineTransportError(onlineError)) throw onlineError;
266|      let library;
267|      try {
268|        library = await loadOfflineLibrary();
269|      } catch {
270|        throw onlineError;
271|      }
272|      if (library === null) throw onlineError;
273|      setMode('offline');
274|      if (options.state !== undefined) options.state.lastFallbackAt = new Date().toISOString();
275|      return offlineCall(library);
276|    }
