334|  ): Promise<{ localKey: string }> {
335|    if (transportError !== undefined && !isOfflineTransportError(transportError)) throw transportError;
336|    if (!hasMediaOutbox(store)) throw new Error('Offline create storage is unavailable');
337|    const active = await readActiveSnapshot(store);
338|    if (active === null) throw new Error('Download an offline copy before creating Entries offline');
339|    if (await store.readMeta(ENTRY_CREATE_CAPABILITY_KEY) !== '1') {
340|      throw new Error('This offline copy has not enabled offline Entry creation; update it while online');
341|    }
342|    const title = input.title.trim();
343|    const type = input.type.trim();
344|    if (title.length === 0 || type.length === 0) throw new Error('Title and Gallery are required');
345|    if (!active.snapshot.payload.entries.some((entry) => entry.type === type)) {
346|      throw new Error('Offline creation can only use an existing Gallery from this offline copy');
347|    }
348|    const files = [
349|      ...(input.coverFile === null ? [] : [{ kind: 'cover' as const, file: input.coverFile }]),
350|      ...(input.previewFile === null ? [] : [{ kind: 'preview' as const, file: input.previewFile }]),
351|    ];
352|    if (files.length > 0 && await store.readMeta(MEDIA_UPLOAD_CAPABILITY_KEY) !== '1') {
353|      throw new Error('This offline copy has not enabled staged media upload; update it while online');
354|    }
355|    const requiredBytes = files.reduce((total, { file }) => total + file.size, 0);
356|    try {
357|      const estimate = await globalThis.navigator?.storage?.estimate();
358|      if (estimate?.quota !== undefined && estimate.usage !== undefined
359|        && estimate.quota - estimate.usage < Math.ceil(requiredBytes * 1.1)) {
360|        throw new Error('Not enough browser storage to stage these offline images');
361|      }
362|    } catch (cause) {
363|      if (cause instanceof Error && cause.message.startsWith('Not enough browser storage')) throw cause;
364|      // Storage estimation is advisory and is absent on some PWA engines. The
365|      // multi-store IndexedDB transaction remains the durability boundary.
366|    }
367|    const entityUid = randomUUID();
368|    const operation = createPendingSyncOperation({
369|      clientId,
370|      libraryId: active.snapshot.header.libraryId,
371|      syncEpoch: active.snapshot.header.syncEpoch,
372|      entityKind: 'entry',
373|      entityUid,
374|      operationKind: 'entry.create',
375|      baseVersion: 0,
376|      baseValues: {},
