391|    for (const { kind, file } of files) {
392|      if (!ALLOWED_MEDIA_TYPES.has(file.type as StagedMediaUpload['mimeType'])) {
393|        throw new Error(`Unsupported offline image type: ${file.type || 'unknown'}`);
394|      }
