128|    clientId: operation.clientId,
129|    libraryId: operation.libraryId,
130|    syncEpoch: operation.syncEpoch,
131|    entityKind: operation.entityKind,
132|    entityUid: operation.entityUid,
133|    operationKind: operation.operationKind,
134|    baseVersion: operation.baseVersion,
135|    baseValues: operation.baseValues,
136|    payload: operation.payload,
