151|type EntryUpdateOperation = Extract<SyncReplayOperation, { operationKind: 'entry.update' }>;
152|type EntryUsageOperation = Extract<SyncReplayOperation, { operationKind: 'entry.usage' }>;
153|type EntryViewLaterOperation = Extract<SyncReplayOperation, { operationKind: 'entry.view-later.set' }>;
154|
155|function isEntryUpdateOperation(
156|  operation: SyncReplayOperation,
157|): operation is EntryUpdateOperation {
158|  return operation.operationKind === 'entry.update';
159|}
160|
161|function isEntryUsageOperation(
162|  operation: SyncReplayOperation,
163|): operation is EntryUsageOperation {
164|  return operation.operationKind === 'entry.usage';
165|}
166|
167|function isEntryViewLaterOperation(
168|  operation: SyncReplayOperation,
169|): operation is EntryViewLaterOperation {
170|  return operation.operationKind === 'entry.view-later.set';
171|}
172|
173|function advancesEntryVersion(operation: SyncReplayOperation): boolean {
174|  return operation.operationKind === 'entry.update'
175|    || operation.operationKind === 'entry.usage'
176|    || operation.operationKind === 'entry.view-later.set';
177|}
178|
179|function applyEntryPatch<T extends SyncSnapshot['payload']['entries'][number]>(
180|  entry: T,
181|  patch: EntryUpdateOperation['payload'],
182|): T {
183|  return {
184|    ...entry,
185|    ...(patch.title !== undefined ? { title: patch.title } : {}),
186|    ...(patch.uploadDate !== undefined ? { uploadDate: patch.uploadDate } : {}),
187|    ...(patch.pageCount !== undefined ? { pageCount: patch.pageCount } : {}),
188|  };
189|}
190|
191|function snapshotWithOverlays(
192|  snapshot: SyncSnapshot,
193|  operations: PendingSyncOperation[],
194|): SyncSnapshot {
195|  const parsed = parsedEntryOperations(operations);
196|  const entryOperations = parsed.filter(isEntryUpdateOperation);
197|  const usageOperations = parsed.filter(isEntryUsageOperation);
198|  const viewLaterOperations = parsed.filter(isEntryViewLaterOperation);
199|  if (entryOperations.length === 0
200|    && usageOperations.length === 0
201|    && viewLaterOperations.length === 0) return snapshot;
202|
203|  const entries = snapshot.payload.entries.map((entry) => {
204|    const patches = entryOperations.filter((operation) => operation.entityUid === entry.syncUid);
205|    return patches.reduce((current, operation) => applyEntryPatch(current, operation.payload), entry);
206|  });
207|  const entryIdsByUid = new Map(entries.map((entry) => [entry.syncUid, entry.id]));
208|  const usageByEntryId = new Map(snapshot.payload.entryUsage.map((usage) => [
209|    usage.entryId,
210|    { ...usage },
211|  ]));
212|  for (const operation of usageOperations) {
213|    const entryId = entryIdsByUid.get(operation.entityUid);
214|    if (entryId === undefined) continue;
215|    const current = usageByEntryId.get(entryId) ?? {
216|      entryId,
217|      viewCount: 0,
218|      likeCount: 0,
219|      lastViewedAt: null,
220|    };
221|    if (operation.payload.event === 'view') {
222|      current.viewCount += 1;
223|      if (current.lastViewedAt === null || operation.clientCreatedAt > current.lastViewedAt) {
224|        current.lastViewedAt = operation.clientCreatedAt;
225|      }
226|    } else {
227|      current.likeCount += 1;
228|    }
229|    usageByEntryId.set(entryId, current);
230|  }
231|  const viewLaterEntries = snapshot.payload.viewLaterEntries.map((membership) => ({ ...membership }));
232|  let nextViewLaterPosition = viewLaterEntries.reduce(
233|    (maximum, membership) => Math.max(maximum, membership.position),
234|    -1,
235|  ) + 1;
236|  for (const operation of viewLaterOperations) {
237|    const entryId = entryIdsByUid.get(operation.entityUid);
238|    if (entryId === undefined) continue;
239|    const existingIndex = viewLaterEntries.findIndex((membership) => membership.subjectId === entryId);
240|    if (operation.payload.present && existingIndex < 0) {
241|      viewLaterEntries.push({ subjectId: entryId, position: nextViewLaterPosition });
242|      nextViewLaterPosition += 1;
243|    } else if (!operation.payload.present && existingIndex >= 0) {
244|      viewLaterEntries.splice(existingIndex, 1);
245|    }
246|  }
247|
248|  return {
249|    ...snapshot,
250|    payload: {
251|      ...snapshot.payload,
252|      entries,
253|      entryUsage: [...usageByEntryId.values()].sort((left, right) => left.entryId - right.entryId),
254|      viewLaterEntries,
255|    },
256|  };
257|}
258|
259|function viewLaterStateFromSnapshot(snapshot: SyncSnapshot): ViewLaterState {
260|  const byPosition = (
261|    left: SyncSnapshot['payload']['viewLaterEntries'][number],
262|    right: SyncSnapshot['payload']['viewLaterEntries'][number],
263|  ) => left.position - right.position || left.subjectId - right.subjectId;
264|  return {
265|    entryIds: [...snapshot.payload.viewLaterEntries].sort(byPosition).map((row) => row.subjectId),
266|    producerIds: [...snapshot.payload.viewLaterProducers].sort(byPosition).map((row) => row.subjectId),
267|  };
268|}
