270|function entryRecordFromSnapshot(
271|  entry: SyncSnapshot['payload']['entries'][number],
272|  patch: UpdateEntryRequest,
273|): EntryRecordDto {
274|  return {
275|    id: entry.id,
276|    title: patch.title ?? entry.title,
277|    type: entry.type,
278|    coverRef: entry.coverRef,
279|    previewRef: entry.previewRef,
280|    previewRefs: entry.previewRefs,
281|    uploadDate: patch.uploadDate === undefined ? entry.uploadDate : patch.uploadDate,
282|    pageCount: patch.pageCount === undefined ? entry.pageCount : patch.pageCount,
283|  };
