302|
303|  async function diagnoseMutation<T>(
304|    action: NonNullable<OfflineApiState['lastMutationDiagnostic']>['action'],
305|    capabilityKey: string,
306|    run: () => Promise<T>,
307|  ): Promise<T> {
308|    let capability: string | null = null;
309|    let beforeCount: number | null = null;
310|    try {
311|      capability = await store.readMeta(capabilityKey);
312|      beforeCount = hasOutbox(store) ? (await store.list()).length : null;
313|    } catch {
314|      // Diagnostics must never change mutation behavior.
315|    }
316|    const diagnostic: NonNullable<OfflineApiState['lastMutationDiagnostic']> = {
317|      at: new Date().toISOString(),
318|      action,
319|      modeBefore: mode,
320|      modeAfter: mode,
321|      capability,
322|      result: 'running',
323|      transportClassified: null,
324|      errorName: null,
325|      errorMessage: null,
326|    };
327|    if (options.state !== undefined) {
328|      options.state.lastMutationDiagnostic = diagnostic;
329|      options.state.mutationDiagnostics = [
330|        ...(options.state.mutationDiagnostics ?? []),
331|        diagnostic,
332|      ].slice(-8);
333|    }
334|    try {
335|      const result = await run();
336|      let afterCount: number | null = null;
337|      try {
338|        afterCount = hasOutbox(store) ? (await store.list()).length : null;
339|      } catch {
340|        // Keep the successful mutation result even if this diagnostic read fails.
341|      }
342|      Object.assign(diagnostic, {
343|        modeAfter: mode,
344|        result: beforeCount !== null && afterCount !== null && afterCount > beforeCount
345|          ? 'queued'
346|          : 'online-or-noop',
347|      });
348|      if (options.state !== undefined) options.state.lastMutationDiagnostic = { ...diagnostic };
349|      return result;
350|    } catch (cause) {
351|      Object.assign(diagnostic, {
352|        modeAfter: mode,
353|        result: 'error',
354|        transportClassified: isOfflineTransportError(cause),
355|        errorName: cause instanceof Error ? cause.name : typeof cause,
356|        errorMessage: cause instanceof Error ? cause.message : String(cause),
357|      });
358|      if (options.state !== undefined) options.state.lastMutationDiagnostic = { ...diagnostic };
359|      throw cause;
360|    }
361|  }
362|
363|  function setReplayState(
364|    pendingCount: number,
365|    conflictCount = 0,
366|    failedCount = 0,
367|    error: string | null = null,
368|  ): void {
369|    if (options.state === undefined) return;
370|    options.state.pendingCount = pendingCount;
371|    options.state.conflictCount = conflictCount;
372|    options.state.failedCount = failedCount;
373|    options.state.lastReplayError = error;
374|  }
375|
376|  function setReplayStateFromOperations(
377|    operations: PendingSyncOperation[],
378|    fallbackError: string | null = null,
379|  ): void {
380|    const pending = operations.filter((operation) => operation.status === 'pending').length;
381|    const conflicts = operations.filter((operation) => operation.status === 'conflict').length;
382|    const failures = operations.filter((operation) => operation.status === 'failed').length;
383|    const storedError = operations.find((operation) => operation.lastError !== null)?.lastError ?? fallbackError;
384|    setReplayState(pending, conflicts, failures, storedError);
385|  }
