387|  async function setReplayStateFromStore(fallbackError: string | null = null): Promise<void> {
388|    const operations = await listOperations();
389|    const media = hasMediaOutbox(store) ? await store.listMedia() : [];
390|    const pending = operations.filter((operation) => operation.status === 'pending').length
391|      + media.filter((upload) => upload.status === 'pending').length;
392|    const conflicts = operations.filter((operation) => operation.status === 'conflict').length;
393|    const failures = operations.filter((operation) => operation.status === 'failed').length
394|      + media.filter((upload) => upload.status === 'failed').length;
395|    const storedError = operations.find((operation) => operation.lastError !== null)?.lastError
396|      ?? media.find((upload) => upload.lastError !== null)?.lastError
397|      ?? fallbackError;
398|    setReplayState(pending, conflicts, failures, storedError);
399|  }
