401|  function invalidateOfflineLibrary(): void {
402|    cachedLibraryKey = null;
403|    cachedLibrary = null;
404|  }
405|
406|  async function listOperations(): Promise<PendingSyncOperation[]> {
407|    return hasOutbox(store) ? store.list() : [];
408|  }
409|
410|  async function loadOfflineLibrary(): Promise<OfflineLibrary | null> {
411|    const generationId = await store.readMeta(ACTIVE_GENERATION_KEY);
412|    if (generationId === null) return null;
413|    const operations = await listOperations();
414|    const key = `${generationId}:${operations.map(operationFingerprint).join('|')}`;
415|    if (cachedLibrary !== null && cachedLibraryKey === key) return cachedLibrary;
416|    const active = await readActiveSnapshot(store);
417|    if (active === null) return null;
418|    cachedLibraryKey = key;
419|    cachedLibrary = createOfflineLibrary(snapshotWithOverlays(active.snapshot, operations));
420|    return cachedLibrary;
421|  }
