423|  async function withFallback<T>(
424|    onlineCall: () => Promise<T>,
425|    offlineCall: (library: OfflineLibrary) => T,
426|  ): Promise<T> {
427|    if (mode === 'offline') {
428|      try {
429|        const library = await loadOfflineLibrary();
430|        if (library !== null) return offlineCall(library);
431|      } catch {
432|        // IndexedDB can be transiently unavailable; retry the authoritative API.
433|      }
434|      setMode('online');
435|    }
436|    try {
437|      const result = await onlineCall();
438|      setMode('online');
439|      return result;
440|    } catch (onlineError) {
441|      if (!isOfflineTransportError(onlineError)) throw onlineError;
442|      let library;
443|      try {
444|        library = await loadOfflineLibrary();
445|      } catch {
446|        throw onlineError;
447|      }
448|      if (library === null) throw onlineError;
449|      setMode('offline');
450|      if (options.state !== undefined) options.state.lastFallbackAt = new Date().toISOString();
451|      return offlineCall(library);
452|    }
453|  }
