455|  async function enqueueEntryUpdate(
456|    entryId: number,
457|    input: UpdateEntryRequest,
458|    transportError: unknown,
459|  ): Promise<EntryRecordDto> {
460|    if (!hasOutbox(store)) throw transportError;
461|    const unsupported = Object.keys(input).some((key) => !['title', 'uploadDate', 'pageCount'].includes(key));
462|    if (unsupported || Object.keys(input).length === 0) throw transportError;
463|    const active = await readActiveSnapshot(store);
464|    const original = active?.snapshot.payload.entries.find((entry) => entry.id === entryId);
465|    if (active === null || original?.syncUid === undefined || original.syncVersion === undefined) {
466|      throw transportError;
467|    }
468|
469|    const operations = await store.list();
470|    const parsed = parsedEntryOperations(operations);
471|    const earlier = parsed
472|      .filter(isEntryUpdateOperation)
473|      .filter((operation) => operation.entityUid === original.syncUid);
474|    const versionAdvances = parsed.filter((operation) => (
475|      operation.entityUid === original.syncUid && advancesEntryVersion(operation)
476|    )).length;
477|    const current = earlier.reduce((entry, operation) => applyEntryPatch(entry, operation.payload), original);
478|    const payload = {
479|      ...(input.title !== undefined ? { title: input.title } : {}),
480|      ...(input.uploadDate !== undefined ? { uploadDate: input.uploadDate } : {}),
481|      ...(input.pageCount !== undefined ? { pageCount: input.pageCount } : {}),
482|    };
483|    const baseValues = {
484|      ...(input.title !== undefined ? { title: current.title } : {}),
485|      ...(input.uploadDate !== undefined ? { uploadDate: current.uploadDate } : {}),
486|      ...(input.pageCount !== undefined ? { pageCount: current.pageCount } : {}),
487|    };
488|    const operation = createPendingSyncOperation({
489|      clientId,
490|      libraryId: active.snapshot.header.libraryId,
491|      syncEpoch: active.snapshot.header.syncEpoch,
492|      entityKind: 'entry',
493|      entityUid: original.syncUid,
494|      operationKind: 'entry.update',
495|      baseVersion: original.syncVersion + versionAdvances,
496|      baseValues,
497|      payload,
498|    }, { randomUUID });
499|    const normalized = {
500|      ...operation,
501|      ...transportOperation(operation),
502|    } as PendingSyncOperation;
503|    await store.enqueue(normalized);
504|    const pending = await store.list();
505|    setReplayStateFromOperations(pending);
506|    invalidateOfflineLibrary();
