607|  async function enqueueOfflineEntryCreate(
608|    input: OfflineEntryCreateRequest,
609|    transportError?: unknown,
610|  ): Promise<{ localKey: string }> {
611|    if (transportError !== undefined && !isOfflineTransportError(transportError)) throw transportError;
612|    if (!hasMediaOutbox(store)) throw new Error('Offline create storage is unavailable');
613|    const active = await readActiveSnapshot(store);
614|    if (active === null) throw new Error('Download an offline copy before creating Entries offline');
615|    if (await store.readMeta(ENTRY_CREATE_CAPABILITY_KEY) !== '1') {
616|      throw new Error('This offline copy has not enabled offline Entry creation; update it while online');
617|    }
618|    const title = input.title.trim();
619|    const type = input.type.trim();
620|    if (title.length === 0 || type.length === 0) throw new Error('Title and Gallery are required');
621|    if (!active.snapshot.payload.entries.some((entry) => entry.type === type)) {
622|      throw new Error('Offline creation can only use an existing Gallery from this offline copy');
623|    }
624|    const files = [
625|      ...(input.coverFile === null ? [] : [{ kind: 'cover' as const, file: input.coverFile }]),
626|      ...(input.previewFile === null ? [] : [{ kind: 'preview' as const, file: input.previewFile }]),
627|    ];
628|    if (files.length > 0 && await store.readMeta(MEDIA_UPLOAD_CAPABILITY_KEY) !== '1') {
629|      throw new Error('This offline copy has not enabled staged media upload; update it while online');
630|    }
631|    const requiredBytes = files.reduce((total, { file }) => total + file.size, 0);
632|    try {
633|      const estimate = await globalThis.navigator?.storage?.estimate();
634|      if (estimate?.quota !== undefined && estimate.usage !== undefined
635|        && estimate.quota - estimate.usage < Math.ceil(requiredBytes * 1.1)) {
636|        throw new Error('Not enough browser storage to stage these offline images');
637|      }
638|    } catch (cause) {
639|      if (cause instanceof Error && cause.message.startsWith('Not enough browser storage')) throw cause;
640|      // Storage estimation is advisory and is absent on some PWA engines. The
641|      // multi-store IndexedDB transaction remains the durability boundary.
642|    }
643|    const entityUid = randomUUID();
644|    const operation = createPendingSyncOperation({
645|      clientId,
646|      libraryId: active.snapshot.header.libraryId,
647|      syncEpoch: active.snapshot.header.syncEpoch,
648|      entityKind: 'entry',
649|      entityUid,
650|      operationKind: 'entry.create',
651|      baseVersion: 0,
652|      baseValues: {},
653|      payload: {
654|        title,
655|        type,
656|        uploadDate: input.uploadDate,
657|        pageCount: input.pageCount,
658|        ratings: [...input.ratings].sort((left, right) => left.slotId - right.slotId),
659|        viewLater: input.viewLater,
660|      },
661|    }, { randomUUID });
662|    const normalized = {
663|      ...operation,
664|      ...transportOperation(operation),
665|    } as PendingSyncOperation;
666|    const media: StagedMediaUpload[] = [];
667|    for (const { kind, file } of files) {
668|      if (!ALLOWED_MEDIA_TYPES.has(file.type as StagedMediaUpload['mimeType'])) {
669|        throw new Error(`Unsupported offline image type: ${file.type || 'unknown'}`);
670|      }
671|      if (file.size <= 0 || file.size > MAX_STAGED_MEDIA_BYTES) {
672|        throw new Error('Offline images must be between 1 byte and 20 MB');
673|      }
674|      media.push({
675|        uploadId: randomUUID(),
676|        libraryId: normalized.libraryId,
677|        syncEpoch: normalized.syncEpoch,
678|        entryUid: entityUid,
679|        kind,
680|        ordinal: 0,
681|        mimeType: file.type as StagedMediaUpload['mimeType'],
682|        byteLength: file.size,
683|        sha256: await sha256Hex(file),
684|        blob: file,
685|        status: 'pending',
686|        lastAttemptAt: null,
687|        lastError: null,
688|      });
689|    }
690|    await store.enqueueEntryCreate(normalized, media);
691|    await setReplayStateFromStore();
692|    invalidateOfflineLibrary();
693|    setMode('offline');
694|    return { localKey: `local:${entityUid}` };
695|  }
