697|  async function listPendingOfflineEntryCreates(): Promise<PendingOfflineEntryCreate[]> {
698|    if (!hasOutbox(store)) return [];
699|    return (await store.list()).flatMap((stored) => {
700|      try {
701|        const operation = transportOperation(stored);
702|        if (operation.operationKind !== 'entry.create') return [];
703|        return [{
