805|  async function replayPendingOperations(): Promise<void> {
806|    if (replayPromise !== null) return replayPromise;
807|    replayPromise = (async () => {
808|      if (!hasOutbox(store) || online.replaySyncOperation === undefined) return;
809|      const operations = await store.list();
810|      const mediaBeforeReplay = hasMediaOutbox(store) ? await store.listMedia() : [];
811|      await setReplayStateFromStore();
812|      if (operations.length === 0 && mediaBeforeReplay.length === 0) return;
813|      const activeBeforeReplay = await readActiveSnapshot(store);
814|      const appliedOperations: SyncReplayOperation[] = [];
815|      const appliedMedia: StagedMediaUpload[] = [];
816|      let maxAppliedServerSeq = -1;
817|      const blockedEntities = new Set<string>();
818|      let replayError: string | null = null;
819|      let attemptedOpId: string | null = null;
820|      let attemptedUploadId: string | null = null;
821|      try {
822|        for (const stored of operations) {
823|          const entityKey = `${stored.entityKind}:${stored.entityUid}`;
824|          if (stored.status !== 'pending') {
825|            blockedEntities.add(entityKey);
826|            replayError ??= stored.lastError;
827|            continue;
828|          }
829|          if (blockedEntities.has(entityKey)) continue;
830|          let operation: SyncReplayOperation;
831|          try {
832|            operation = transportOperation(stored);
833|          } catch {
834|            // An envelope this build can no longer express (for example one queued
835|            // by another app version) must neither be sent nor silently dropped,
836|            // and it must not stop unrelated Entries from syncing.
837|            replayError = 'Invalid offline operation: this version cannot send it';
838|            await store.update(stored.opId, { status: 'failed', lastError: replayError });
839|            blockedEntities.add(entityKey);
840|            continue;
841|          }
842|          attemptedOpId = stored.opId;
843|          await store.update(stored.opId, {
844|            lastAttemptAt: new Date().toISOString(),
845|            lastError: null,
846|          });
847|          const result = await online.replaySyncOperation(operation);
848|          if (result.status === 'applied') {
849|            appliedOperations.push(operation);
850|            maxAppliedServerSeq = Math.max(maxAppliedServerSeq, result.serverSeq);
851|            attemptedOpId = null;
852|            continue;
853|          }
854|          if (result.status === 'conflict') {
855|            replayError = 'An offline edit conflicts with a newer server value';
856|            await store.update(stored.opId, { status: 'conflict', lastError: replayError });
857|          } else if (result.status === 'resnapshot-required') {
858|            replayError = 'The library changed and the offline edit needs review';
859|            await store.update(stored.opId, { status: 'conflict', lastError: replayError });
860|          } else {
861|            replayError = result.detail;
862|            await store.update(stored.opId, { status: 'failed', lastError: replayError });
863|          }
864|          blockedEntities.add(entityKey);
865|          attemptedOpId = null;
866|        }
867|
868|        if (hasMediaOutbox(store) && online.uploadSyncMedia !== undefined) {
869|          const readyEntryUids = new Set(
870|            activeBeforeReplay?.snapshot.payload.entries.map((entry) => entry.syncUid) ?? [],
871|          );
872|          for (const operation of appliedOperations) {
873|            if (operation.operationKind === 'entry.create') readyEntryUids.add(operation.entityUid);
874|          }
875|          for (const upload of mediaBeforeReplay) {
876|            if (upload.status !== 'pending' || !readyEntryUids.has(upload.entryUid)) continue;
877|            attemptedUploadId = upload.uploadId;
878|            await store.updateMedia(upload.uploadId, {
879|              lastAttemptAt: new Date().toISOString(),
880|              lastError: null,
881|            });
882|            try {
883|              const result = await online.uploadSyncMedia(upload.uploadId, {
884|                libraryId: upload.libraryId,
885|                syncEpoch: upload.syncEpoch,
886|                entryUid: upload.entryUid,
887|                kind: upload.kind,
888|                ordinal: upload.ordinal,
889|                mimeType: upload.mimeType,
890|                byteLength: upload.byteLength,
891|                sha256: upload.sha256,
892|              }, upload.blob);
893|              appliedMedia.push(upload);
894|              maxAppliedServerSeq = Math.max(maxAppliedServerSeq, result.serverSeq);
895|              attemptedUploadId = null;
896|            } catch (cause) {
897|              if (cause instanceof ApiError && [400, 404, 409].includes(cause.status)) {
898|                replayError = cause.message;
899|                await store.updateMedia(upload.uploadId, { status: 'failed', lastError: replayError });
900|                attemptedUploadId = null;
901|                continue;
902|              }
903|              throw cause;
904|            }
905|          }
906|        }
907|
908|        if (appliedOperations.length > 0 || appliedMedia.length > 0) {
909|          const first = appliedOperations[0];
910|          const snapshot = await online.fetchSyncSnapshot();
911|          if (snapshot.header.changeSeq === undefined || snapshot.header.changeSeq < maxAppliedServerSeq) {
912|            throw new Error(
913|              `Snapshot refresh failed: change sequence ${String(snapshot.header.changeSeq)} does not cover replay ${maxAppliedServerSeq}`,
914|            );
915|          }
916|          const currentLibraryId = first?.libraryId
917|            ?? activeBeforeReplay?.snapshot.header.libraryId;
918|          const currentSyncEpoch = first?.syncEpoch
919|            ?? activeBeforeReplay?.snapshot.header.syncEpoch;
920|          if (currentLibraryId === undefined || currentSyncEpoch === undefined) {
921|            throw new Error('Snapshot refresh failed: no paired offline library identity');
922|          }
923|          const applied = await applySnapshot(snapshot, {
924|            store,
925|            currentLibraryId,
926|            currentSyncEpoch,
927|            ...(activeBeforeReplay === null
928|              ? {}
929|              : { currentSnapshotSeq: activeBeforeReplay.snapshot.header.snapshotSeq }),
930|          });
931|          if (!applied.ok) throw new Error(`Snapshot refresh failed: ${applied.failure.reason}`);
932|          for (const operation of appliedOperations) await store.remove(operation.opId);
933|          if (hasMediaOutbox(store)) {
934|            for (const upload of appliedMedia) await store.removeMedia(upload.uploadId);
935|          }
936|          invalidateOfflineLibrary();
937|        }
938|      } catch (cause) {
939|        replayError = cause instanceof Error ? cause.message : String(cause);
940|        if (attemptedOpId !== null) {
941|          await store.update(attemptedOpId, { status: 'pending', lastError: replayError });
942|        }
943|        if (attemptedUploadId !== null && hasMediaOutbox(store)) {
944|          await store.updateMedia(attemptedUploadId, { status: 'pending', lastError: replayError });
945|        }
946|      } finally {
947|        await setReplayStateFromStore(replayError);
948|      }
949|    })().finally(() => {
950|      replayPromise = null;
951|    });
952|    return replayPromise;
953|  }
