457|  async function withFallback<T>(
458|    onlineCall: () => Promise<T>,
459|    offlineCall: (library: OfflineLibrary) => T,
460|  ): Promise<T> {
461|    if (mode === 'offline') {
462|      try {
463|        const library = await loadOfflineLibrary();
464|        if (library !== null) return offlineCall(library);
465|      } catch {
466|        // IndexedDB can be transiently unavailable; retry the authoritative API.
467|      }
468|      setMode('online');
469|    }
470|    try {
471|      const result = await onlineCall();
472|      setMode('online');
473|      return result;
474|    } catch (onlineError) {
475|      if (!isOfflineTransportError(onlineError)) throw onlineError;
476|      let library;
477|      try {
478|        library = await loadOfflineLibrary();
479|      } catch {
480|        throw onlineError;
481|      }
482|      if (library === null) throw onlineError;
483|      setMode('offline');
484|      if (options.state !== undefined) options.state.lastFallbackAt = new Date().toISOString();
485|      return offlineCall(library);
486|    }
487|  }
