489|  async function enqueueEntryUpdate(
490|    entryId: number,
491|    input: UpdateEntryRequest,
492|    transportError: unknown,
493|  ): Promise<EntryRecordDto> {
494|    if (!hasOutbox(store)) throw transportError;
495|    const unsupported = Object.keys(input).some((key) => !['title', 'uploadDate', 'pageCount'].includes(key));
496|    if (unsupported || Object.keys(input).length === 0) throw transportError;
497|    const active = await readActiveSnapshot(store);
498|    const original = active?.snapshot.payload.entries.find((entry) => entry.id === entryId);
499|    if (active === null || original?.syncUid === undefined || original.syncVersion === undefined) {
500|      throw transportError;
501|    }
502|
503|    const operations = await store.list();
504|    const parsed = parsedEntryOperations(operations);
505|    const earlier = parsed
506|      .filter(isEntryUpdateOperation)
507|      .filter((operation) => operation.entityUid === original.syncUid);
508|    const versionAdvances = parsed.filter((operation) => (
509|      operation.entityUid === original.syncUid && advancesEntryVersion(operation)
510|    )).length;
511|    const current = earlier.reduce((entry, operation) => applyEntryPatch(entry, operation.payload), original);
512|    const payload = {
513|      ...(input.title !== undefined ? { title: input.title } : {}),
514|      ...(input.uploadDate !== undefined ? { uploadDate: input.uploadDate } : {}),
515|      ...(input.pageCount !== undefined ? { pageCount: input.pageCount } : {}),
516|    };
517|    const baseValues = {
518|      ...(input.title !== undefined ? { title: current.title } : {}),
519|      ...(input.uploadDate !== undefined ? { uploadDate: current.uploadDate } : {}),
520|      ...(input.pageCount !== undefined ? { pageCount: current.pageCount } : {}),
521|    };
522|    const operation = createPendingSyncOperation({
523|      clientId,
524|      libraryId: active.snapshot.header.libraryId,
525|      syncEpoch: active.snapshot.header.syncEpoch,
526|      entityKind: 'entry',
527|      entityUid: original.syncUid,
528|      operationKind: 'entry.update',
529|      baseVersion: original.syncVersion + versionAdvances,
530|      baseValues,
531|      payload,
532|    }, { randomUUID });
533|    const normalized = {
534|      ...operation,
535|      ...transportOperation(operation),
536|    } as PendingSyncOperation;
537|    await store.enqueue(normalized);
538|    const pending = await store.list();
539|    setReplayStateFromOperations(pending);
540|    invalidateOfflineLibrary();
