701|  async function enqueueOfflineEntryCreate(
702|    input: OfflineEntryCreateRequest,
703|    transportError?: unknown,
704|  ): Promise<{ localKey: string }> {
705|    if (transportError !== undefined && !isOfflineTransportError(transportError)) throw transportError;
706|    if (!hasMediaOutbox(store)) throw new Error('Offline create storage is unavailable');
707|    const active = await readActiveSnapshot(store);
708|    if (active === null) throw new Error('Download an offline copy before creating Entries offline');
709|    if (await store.readMeta(ENTRY_CREATE_CAPABILITY_KEY) !== '1') {
710|      throw new Error('This offline copy has not enabled offline Entry creation; update it while online');
711|    }
712|    const title = input.title.trim();
713|    const type = input.type.trim();
714|    if (title.length === 0 || type.length === 0) throw new Error('Title and Gallery are required');
715|    if (!active.snapshot.payload.entries.some((entry) => entry.type === type)) {
716|      throw new Error('Offline creation can only use an existing Gallery from this offline copy');
717|    }
718|    const files = [
719|      ...(input.coverFile === null ? [] : [{ kind: 'cover' as const, file: input.coverFile }]),
720|      ...(input.previewFile === null ? [] : [{ kind: 'preview' as const, file: input.previewFile }]),
721|    ];
722|    if (files.length > 0 && await store.readMeta(MEDIA_UPLOAD_CAPABILITY_KEY) !== '1') {
723|      throw new Error('This offline copy has not enabled staged media upload; update it while online');
724|    }
725|    const requiredBytes = files.reduce((total, { file }) => total + file.size, 0);
726|    try {
727|      const estimate = await globalThis.navigator?.storage?.estimate();
728|      if (estimate?.quota !== undefined && estimate.usage !== undefined
729|        && estimate.quota - estimate.usage < Math.ceil(requiredBytes * 1.1)) {
730|        throw new Error('Not enough browser storage to stage these offline images');
731|      }
732|    } catch (cause) {
733|      if (cause instanceof Error && cause.message.startsWith('Not enough browser storage')) throw cause;
734|      // Storage estimation is advisory and is absent on some PWA engines. The
735|      // multi-store IndexedDB transaction remains the durability boundary.
736|    }
737|    const entityUid = randomUUID();
738|    const operation = createPendingSyncOperation({
739|      clientId,
740|      libraryId: active.snapshot.header.libraryId,
741|      syncEpoch: active.snapshot.header.syncEpoch,
742|      entityKind: 'entry',
743|      entityUid,
744|      operationKind: 'entry.create',
745|      baseVersion: 0,
746|      baseValues: {},
747|      payload: {
748|        title,
749|        type,
750|        uploadDate: input.uploadDate,
751|        pageCount: input.pageCount,
752|        ratings: [...input.ratings].sort((left, right) => left.slotId - right.slotId),
753|        viewLater: input.viewLater,
754|      },
755|    }, { randomUUID });
756|    const normalized = {
757|      ...operation,
758|      ...transportOperation(operation),
759|    } as PendingSyncOperation;
760|    const media: StagedMediaUpload[] = [];
761|    for (const { kind, file } of files) {
762|      if (!ALLOWED_MEDIA_TYPES.has(file.type as StagedMediaUpload['mimeType'])) {
763|        throw new Error(`Unsupported offline image type: ${file.type || 'unknown'}`);
764|      }
765|      if (file.size <= 0 || file.size > MAX_STAGED_MEDIA_BYTES) {
766|        throw new Error('Offline images must be between 1 byte and 20 MB');
767|      }
768|      media.push({
769|        uploadId: randomUUID(),
770|        libraryId: normalized.libraryId,
771|        syncEpoch: normalized.syncEpoch,
772|        entryUid: entityUid,
773|        kind,
774|        ordinal: 0,
775|        mimeType: file.type as StagedMediaUpload['mimeType'],
776|        byteLength: file.size,
777|        sha256: await sha256Hex(file),
778|        blob: file,
779|        status: 'pending',
780|        lastAttemptAt: null,
781|        lastError: null,
782|      });
783|    }
784|    await store.enqueueEntryCreate(normalized, media);
785|    await setReplayStateFromStore();
786|    invalidateOfflineLibrary();
787|    setMode('offline');
788|    return { localKey: `local:${entityUid}` };
789|  }
