811|  async function replayPendingOperations(): Promise<void> {
812|    if (replayPromise !== null) return replayPromise;
813|    replayPromise = (async () => {
814|      if (!hasOutbox(store) || online.replaySyncOperation === undefined) return;
815|      const operations = await store.list();
816|      const mediaBeforeReplay = hasMediaOutbox(store) ? await store.listMedia() : [];
817|      await setReplayStateFromStore();
818|      if (operations.length === 0 && mediaBeforeReplay.length === 0) return;
819|      const activeBeforeReplay = await readActiveSnapshot(store);
820|      const appliedOperations: SyncReplayOperation[] = [];
821|      const appliedMedia: StagedMediaUpload[] = [];
822|      let maxAppliedServerSeq = -1;
823|      const blockedEntities = new Set<string>();
824|      let replayError: string | null = null;
825|      let attemptedOpId: string | null = null;
826|      let attemptedUploadId: string | null = null;
827|      try {
828|        for (const stored of operations) {
829|          const entityKey = `${stored.entityKind}:${stored.entityUid}`;
830|          if (stored.status !== 'pending') {
831|            blockedEntities.add(entityKey);
832|            replayError ??= stored.lastError;
833|            continue;
834|          }
835|          if (blockedEntities.has(entityKey)) continue;
836|          let operation: SyncReplayOperation;
837|          try {
838|            operation = transportOperation(stored);
839|          } catch {
840|            // An envelope this build can no longer express (for example one queued
841|            // by another app version) must neither be sent nor silently dropped,
842|            // and it must not stop unrelated Entries from syncing.
843|            replayError = 'Invalid offline operation: this version cannot send it';
844|            await store.update(stored.opId, { status: 'failed', lastError: replayError });
845|            blockedEntities.add(entityKey);
846|            continue;
847|          }
848|          attemptedOpId = stored.opId;
849|          await store.update(stored.opId, {
850|            lastAttemptAt: new Date().toISOString(),
851|            lastError: null,
852|          });
853|          const result = await online.replaySyncOperation(operation);
854|          if (result.status === 'applied') {
855|            appliedOperations.push(operation);
856|            maxAppliedServerSeq = Math.max(maxAppliedServerSeq, result.serverSeq);
857|            attemptedOpId = null;
858|            continue;
859|          }
860|          if (result.status === 'conflict') {
861|            replayError = 'An offline edit conflicts with a newer server value';
862|            await store.update(stored.opId, { status: 'conflict', lastError: replayError });
863|          } else if (result.status === 'resnapshot-required') {
864|            replayError = 'The library changed and the offline edit needs review';
865|            await store.update(stored.opId, { status: 'conflict', lastError: replayError });
866|          } else {
867|            replayError = result.detail;
868|            await store.update(stored.opId, { status: 'failed', lastError: replayError });
869|          }
870|          blockedEntities.add(entityKey);
871|          attemptedOpId = null;
872|        }
873|
874|        if (hasMediaOutbox(store) && online.uploadSyncMedia !== undefined) {
875|          const readyEntryUids = new Set(
876|            activeBeforeReplay?.snapshot.payload.entries.map((entry) => entry.syncUid) ?? [],
877|          );
878|          for (const operation of appliedOperations) {
879|            if (operation.operationKind === 'entry.create') readyEntryUids.add(operation.entityUid);
880|          }
881|          for (const upload of mediaBeforeReplay) {
882|            if (upload.status !== 'pending' || !readyEntryUids.has(upload.entryUid)) continue;
883|            attemptedUploadId = upload.uploadId;
884|            await store.updateMedia(upload.uploadId, {
885|              lastAttemptAt: new Date().toISOString(),
886|              lastError: null,
887|            });
888|            try {
889|              const result = await online.uploadSyncMedia(upload.uploadId, {
890|                libraryId: upload.libraryId,
891|                syncEpoch: upload.syncEpoch,
892|                entryUid: upload.entryUid,
893|                kind: upload.kind,
894|                ordinal: upload.ordinal,
895|                mimeType: upload.mimeType,
896|                byteLength: upload.byteLength,
897|                sha256: upload.sha256,
898|              }, upload.blob);
899|              appliedMedia.push(upload);
900|              maxAppliedServerSeq = Math.max(maxAppliedServerSeq, result.serverSeq);
901|              attemptedUploadId = null;
902|            } catch (cause) {
903|              if (cause instanceof ApiError && [400, 404, 409].includes(cause.status)) {
904|                replayError = cause.message;
905|                await store.updateMedia(upload.uploadId, { status: 'failed', lastError: replayError });
906|                attemptedUploadId = null;
907|                continue;
908|              }
909|              throw cause;
910|            }
911|          }
912|        }
913|
914|        if (appliedOperations.length > 0 || appliedMedia.length > 0) {
915|          const first = appliedOperations[0];
916|          const snapshot = await online.fetchSyncSnapshot();
917|          if (snapshot.header.changeSeq === undefined || snapshot.header.changeSeq < maxAppliedServerSeq) {
918|            throw new Error(
919|              `Snapshot refresh failed: change sequence ${String(snapshot.header.changeSeq)} does not cover replay ${maxAppliedServerSeq}`,
920|            );
921|          }
922|          const currentLibraryId = first?.libraryId
923|            ?? activeBeforeReplay?.snapshot.header.libraryId;
924|          const currentSyncEpoch = first?.syncEpoch
925|            ?? activeBeforeReplay?.snapshot.header.syncEpoch;
926|          if (currentLibraryId === undefined || currentSyncEpoch === undefined) {
927|            throw new Error('Snapshot refresh failed: no paired offline library identity');
928|          }
929|          const applied = await applySnapshot(snapshot, {
930|            store,
931|            currentLibraryId,
932|            currentSyncEpoch,
933|            ...(activeBeforeReplay === null
934|              ? {}
935|              : { currentSnapshotSeq: activeBeforeReplay.snapshot.header.snapshotSeq }),
936|          });
937|          if (!applied.ok) throw new Error(`Snapshot refresh failed: ${applied.failure.reason}`);
938|          for (const operation of appliedOperations) await store.remove(operation.opId);
939|          if (hasMediaOutbox(store)) {
940|            for (const upload of appliedMedia) await store.removeMedia(upload.uploadId);
941|          }
