218|    const patches = entryOperations.filter((operation) => operation.entityUid === entry.syncUid);
219|    return patches.reduce((current, operation) => applyEntryPatch(current, operation.payload), entry);
220|  });
221|  const entryIdsByUid = new Map(entries.map((entry) => [entry.syncUid, entry.id]));
222|  const usageByEntryId = new Map(snapshot.payload.entryUsage.map((usage) => [
223|    usage.entryId,
224|    { ...usage },
225|  ]));
226|  for (const operation of usageOperations) {
227|    const entryId = entryIdsByUid.get(operation.entityUid);
228|    if (entryId === undefined) continue;
229|    const current = usageByEntryId.get(entryId) ?? {
230|      entryId,
231|      viewCount: 0,
232|      likeCount: 0,
233|      lastViewedAt: null,
234|    };
235|    if (operation.payload.event === 'view') {
236|      current.viewCount += 1;
237|      if (current.lastViewedAt === null || operation.clientCreatedAt > current.lastViewedAt) {
238|        current.lastViewedAt = operation.clientCreatedAt;
239|      }
