247|    (maximum, membership) => Math.max(maximum, membership.position),
248|    -1,
249|  ) + 1;
250|  for (const operation of viewLaterOperations) {
251|    const entryId = entryIdsByUid.get(operation.entityUid);
252|    if (entryId === undefined) continue;
253|    const existingIndex = viewLaterEntries.findIndex((membership) => membership.subjectId === entryId);
