263|    slot.syncUid === undefined ? [] : [[slot.syncUid, slot.id] as const]
264|  )));
265|  for (const operation of ratingOperations) {
266|    const entryId = entryIdsByUid.get(operation.entityUid);
267|    const slotId = ratingSlotIdsByUid.get(operation.payload.slotUid);
268|    if (entryId === undefined || slotId === undefined) continue;
269|    const existingIndex = entryRatingValues.findIndex((value) => (
270|      value.entryId === entryId && value.slotId === slotId
