281|  return {
282|    ...snapshot,
283|    payload: {
284|      ...snapshot.payload,
285|      entries,
286|      entryUsage: [...usageByEntryId.values()].sort((left, right) => left.entryId - right.entryId),
287|      viewLaterEntries,
288|      entryRatingValues,
289|    },
290|  };
291|}
