337|  async function diagnoseMutation<T>(
338|    action: NonNullable<OfflineApiState['lastMutationDiagnostic']>['action'],
339|    capabilityKey: string,
340|    run: () => Promise<T>,
341|  ): Promise<T> {
342|    let capability: string | null = null;
343|    let beforeCount: number | null = null;
344|    try {
345|      capability = await store.readMeta(capabilityKey);
346|      beforeCount = hasOutbox(store) ? (await store.list()).length : null;
347|    } catch {
348|      // Diagnostics must never change mutation behavior.
349|    }
350|    const diagnostic: NonNullable<OfflineApiState['lastMutationDiagnostic']> = {
351|      at: new Date().toISOString(),
352|      action,
353|      modeBefore: mode,
354|      modeAfter: mode,
355|      capability,
356|      result: 'running',
357|      transportClassified: null,
358|      errorName: null,
359|      errorMessage: null,
360|    };
361|    if (options.state !== undefined) {
362|      options.state.lastMutationDiagnostic = diagnostic;
363|      options.state.mutationDiagnostics = [
364|        ...(options.state.mutationDiagnostics ?? []),
365|        diagnostic,
366|      ].slice(-8);
367|    }
368|    try {
369|      const result = await run();
370|      let afterCount: number | null = null;
371|      try {
372|        afterCount = hasOutbox(store) ? (await store.list()).length : null;
373|      } catch {
374|        // Keep the successful mutation result even if this diagnostic read fails.
375|      }
376|      Object.assign(diagnostic, {
377|        modeAfter: mode,
378|        result: beforeCount !== null && afterCount !== null && afterCount > beforeCount
379|          ? 'queued'
380|          : 'online-or-noop',
381|      });
382|      if (options.state !== undefined) options.state.lastMutationDiagnostic = { ...diagnostic };
383|      return result;
384|    } catch (cause) {
385|      Object.assign(diagnostic, {
386|        modeAfter: mode,
387|        result: 'error',
388|        transportClassified: isOfflineTransportError(cause),
389|        errorName: cause instanceof Error ? cause.name : typeof cause,
390|        errorMessage: cause instanceof Error ? cause.message : String(cause),
391|      });
392|      if (options.state !== undefined) options.state.lastMutationDiagnostic = { ...diagnostic };
393|      throw cause;
394|    }
