415|    const conflicts = operations.filter((operation) => operation.status === 'conflict').length;
416|    const failures = operations.filter((operation) => operation.status === 'failed').length;
417|    const storedError = operations.find((operation) => operation.lastError !== null)?.lastError ?? fallbackError;
418|    setReplayState(pending, conflicts, failures, storedError);
