424|    const pending = operations.filter((operation) => operation.status === 'pending').length
425|      + media.filter((upload) => upload.status === 'pending').length;
426|    const conflicts = operations.filter((operation) => operation.status === 'conflict').length;
427|    const failures = operations.filter((operation) => operation.status === 'failed').length
428|      + media.filter((upload) => upload.status === 'failed').length;
429|    const storedError = operations.find((operation) => operation.lastError !== null)?.lastError
