528|      } catch {
529|        throw onlineError;
530|      }
531|      if (library === null) throw onlineError;
532|      setMode('offline');
533|      if (options.state !== undefined) options.state.lastFallbackAt = new Date().toISOString();
534|      return offlineCall(library);
