509|    const generationId = await store.readMeta(ACTIVE_GENERATION_KEY);
510|    if (generationId === null) return null;
511|    const operations = await listOperations();
512|    const key = `${generationId}:${operations.map(operationFingerprint).join('|')}`;
513|    if (cachedLibrary !== null && cachedLibraryKey === key) return cachedLibrary;
514|    const active = await readActiveSnapshot(store);
