521|  async function withFallback<T>(
522|    onlineCall: () => Promise<T>,
523|    offlineCall: (library: OfflineLibrary) => T,
524|  ): Promise<T> {
525|    if (mode === 'offline') {
526|      try {
527|        const library = await loadOfflineLibrary();
528|        if (library !== null) return offlineCall(library);
529|      } catch {
530|        // IndexedDB can be transiently unavailable; retry the authoritative API.
531|      }
532|      setMode('online');
533|    }
534|    try {
535|      const result = await onlineCall();
536|      setMode('online');
537|      return result;
538|    } catch (onlineError) {
539|      if (!isOfflineTransportError(onlineError)) throw onlineError;
540|      let library;
541|      try {
542|        library = await loadOfflineLibrary();
543|      } catch {
544|        throw onlineError;
545|      }
546|      if (library === null) throw onlineError;
547|      setMode('offline');
548|      if (options.state !== undefined) options.state.lastFallbackAt = new Date().toISOString();
549|      return offlineCall(library);
550|    }
551|  }
