553|  async function enqueueEntryUpdate(
554|    entryId: number,
555|    input: UpdateEntryRequest,
556|    transportError: unknown,
557|  ): Promise<EntryRecordDto> {
558|    if (!hasOutbox(store)) throw transportError;
559|    const unsupported = Object.keys(input).some((key) => !['title', 'uploadDate', 'pageCount'].includes(key));
560|    if (unsupported || Object.keys(input).length === 0) throw transportError;
561|    const active = await readActiveSnapshot(store);
562|    const original = active?.snapshot.payload.entries.find((entry) => entry.id === entryId);
563|    if (active === null || original?.syncUid === undefined || original.syncVersion === undefined) {
564|      throw transportError;
565|    }
566|
567|    const operations = await store.list();
568|    const parsed = parsedEntryOperations(operations);
569|    const earlier = parsed
570|      .filter(isEntryUpdateOperation)
571|      .filter((operation) => operation.entityUid === original.syncUid);
572|    const versionAdvances = parsed.filter((operation) => (
573|      operation.entityUid === original.syncUid && advancesEntryVersion(operation)
574|    )).length;
575|    const current = earlier.reduce((entry, operation) => applyEntryPatch(entry, operation.payload), original);
576|    const payload = {
577|      ...(input.title !== undefined ? { title: input.title } : {}),
578|      ...(input.uploadDate !== undefined ? { uploadDate: input.uploadDate } : {}),
579|      ...(input.pageCount !== undefined ? { pageCount: input.pageCount } : {}),
580|    };
581|    const baseValues = {
582|      ...(input.title !== undefined ? { title: current.title } : {}),
583|      ...(input.uploadDate !== undefined ? { uploadDate: current.uploadDate } : {}),
584|      ...(input.pageCount !== undefined ? { pageCount: current.pageCount } : {}),
585|    };
586|    const operation = createPendingSyncOperation({
587|      clientId,
588|      libraryId: active.snapshot.header.libraryId,
589|      syncEpoch: active.snapshot.header.syncEpoch,
590|      entityKind: 'entry',
591|      entityUid: original.syncUid,
592|      operationKind: 'entry.update',
593|      baseVersion: original.syncVersion + versionAdvances,
594|      baseValues,
595|      payload,
596|    }, { randomUUID });
597|    const normalized = {
598|      ...operation,
599|      ...transportOperation(operation),
600|    } as PendingSyncOperation;
601|    await store.enqueue(normalized);
602|    const pending = await store.list();
603|    setReplayStateFromOperations(pending);
604|    invalidateOfflineLibrary();
605|    setMode('offline');
606|    return entryRecordFromSnapshot(current, input);
607|  }
