99|async function boundedRead<T>(read: () => Promise<T>, timeoutMs: number): Promise<T> {
100|  let timeout: ReturnType<typeof setTimeout> | undefined;
101|  try {
102|    return await Promise.race([
103|      read(),
104|      new Promise<never>((_, reject) => {
105|        timeout = setTimeout(() => reject(new OfflineReadTimeout()), timeoutMs);
106|      }),
107|    ]);
108|  } finally {
109|    if (timeout !== undefined) clearTimeout(timeout);
110|  }
