444|  async function diagnoseMutation<T>(
445|    action: NonNullable<OfflineApiState['lastMutationDiagnostic']>['action'],
446|    capabilityKey: string,
447|    run: () => Promise<T>,
448|  ): Promise<T> {
449|    let capability: string | null = null;
450|    let beforeCount: number | null = null;
451|    try {
452|      capability = await store.readMeta(capabilityKey);
453|      beforeCount = hasOutbox(store) ? (await store.list()).length : null;
454|    } catch {
455|      // Diagnostics must never change mutation behavior.
456|    }
457|    const diagnostic: NonNullable<OfflineApiState['lastMutationDiagnostic']> = {
458|      at: new Date().toISOString(),
459|      action,
460|      modeBefore: mode,
461|      modeAfter: mode,
462|      capability,
463|      result: 'running',
464|      transportClassified: null,
465|      errorName: null,
466|      errorMessage: null,
467|    };
468|    if (options.state !== undefined) {
469|      options.state.lastMutationDiagnostic = diagnostic;
470|      options.state.mutationDiagnostics = [
471|        ...(options.state.mutationDiagnostics ?? []),
472|        diagnostic,
473|      ].slice(-8);
474|    }
475|    try {
476|      const result = await run();
477|      let afterCount: number | null = null;
478|      try {
479|        afterCount = hasOutbox(store) ? (await store.list()).length : null;
480|      } catch {
481|        // Keep the successful mutation result even if this diagnostic read fails.
482|      }
483|      Object.assign(diagnostic, {
484|        modeAfter: mode,
485|        result: beforeCount !== null && afterCount !== null && afterCount > beforeCount
486|          ? 'queued'
487|          : 'online-or-noop',
488|      });
489|      if (options.state !== undefined) options.state.lastMutationDiagnostic = { ...diagnostic };
490|      return result;
491|    } catch (cause) {
492|      Object.assign(diagnostic, {
493|        modeAfter: mode,
494|        result: 'error',
495|        transportClassified: isOfflineTransportError(cause),
496|        errorName: cause instanceof Error ? cause.name : typeof cause,
497|        errorMessage: cause instanceof Error ? cause.message : String(cause),
498|      });
499|      if (options.state !== undefined) options.state.lastMutationDiagnostic = { ...diagnostic };
500|      throw cause;
501|    }
502|  }
503|
504|  function setReplayState(
505|    pendingCount: number,
506|    conflictCount = 0,
507|    failedCount = 0,
508|    error: string | null = null,
509|  ): void {
510|    if (options.state === undefined) return;
511|    options.state.pendingCount = pendingCount;
512|    options.state.conflictCount = conflictCount;
513|    options.state.failedCount = failedCount;
514|    options.state.lastReplayError = error;
515|  }
516|
517|  function setReplayStateFromOperations(
518|    operations: PendingSyncOperation[],
519|    fallbackError: string | null = null,
520|  ): void {
521|    const pending = operations.filter((operation) => operation.status === 'pending').length;
522|    const conflicts = operations.filter((operation) => operation.status === 'conflict').length;
523|    const failures = operations.filter((operation) => operation.status === 'failed').length;
524|    const storedError = operations.find((operation) => operation.lastError !== null)?.lastError ?? fallbackError;
525|    setReplayState(pending, conflicts, failures, storedError);
526|  }
