528|  async function setReplayStateFromStore(fallbackError: string | null = null): Promise<void> {
529|    const operations = await listOperations();
530|    const media = hasMediaOutbox(store) ? await store.listMedia() : [];
531|    const pending = operations.filter((operation) => operation.status === 'pending').length
532|      + media.filter((upload) => upload.status === 'pending').length;
533|    const conflicts = operations.filter((operation) => operation.status === 'conflict').length;
534|    const failures = operations.filter((operation) => operation.status === 'failed').length
535|      + media.filter((upload) => upload.status === 'failed').length;
536|    const storedError = operations.find((operation) => operation.lastError !== null)?.lastError
537|      ?? media.find((upload) => upload.lastError !== null)?.lastError
538|      ?? fallbackError;
539|    setReplayState(pending, conflicts, failures, storedError);
