541|
542|  function invalidateOfflineLibrary(): void {
543|    cachedLibraryKey = null;
544|    cachedLibrary = null;
545|    loadingLibrary = null;
546|  }
547|
548|  async function listOperations(): Promise<PendingSyncOperation[]> {
549|    return hasOutbox(store) ? store.list() : [];
550|  }
551|
552|  async function loadOfflineLibrary(): Promise<OfflineLibrary | null> {
553|    if (loadingLibrary !== null) return loadingLibrary;
554|    const pending = (async () => {
555|      const startedAt = performance.now();
556|      const generationId = await store.readMeta(ACTIVE_GENERATION_KEY);
557|      if (generationId === null || generationId === '0') return null;
558|      const operations = await listOperations();
559|      const key = `${generationId}:${operations.map(operationFingerprint).join('|')}`;
560|      if (cachedLibrary !== null && cachedLibraryKey === key) return cachedLibrary;
561|      const active = await readActiveSnapshot(store);
562|      if (active === null) return null;
563|      const library = createOfflineLibrary(snapshotWithOverlays(active.snapshot, operations));
564|      if (options.state !== undefined) options.state.lastLocalLoadMs = Math.round(performance.now() - startedAt);
565|      cachedLibraryKey = key;
566|      cachedLibrary = library;
567|      return library;
568|    })();
569|    loadingLibrary = pending;
570|    try {
571|      return await pending;
572|    } finally {
573|      if (loadingLibrary === pending) loadingLibrary = null;
574|    }
575|  }
