577|  async function withFallback<T>(
578|    onlineCall: () => Promise<T>,
579|    offlineCall: (library: OfflineLibrary) => T,
580|  ): Promise<T> {
581|    if (mode === 'offline') {
582|      try {
583|        const library = await loadOfflineLibrary();
584|        if (library !== null) {
585|          // An authoritative probe can finish while the large local copy is
586|          // opening. Never let an older offline read overwrite that transition.
587|          if (isOnlineMode()) return withFallback(onlineCall, offlineCall);
588|          setConnectionPhase(null);
589|          return offlineCall(library);
590|        }
591|      } catch {
592|        // IndexedDB can be transiently unavailable; retry the authoritative API.
593|      }
594|      setMode('online');
595|      setConnectionPhase('no-copy');
596|    }
597|    try {
598|      const result = await boundedRead(onlineCall, options.onlineReadTimeoutMs ?? 3_000);
599|      setMode('online');
600|      setConnectionPhase(null);
601|      return result;
602|    } catch (onlineError) {
603|      // A deadline is safe for reads, never for writes: a late completed write
604|      // could otherwise be replayed a second time.
605|      if (!isOfflineTransportError(onlineError) && !(onlineError instanceof OfflineReadTimeout)) {
606|        throw onlineError;
607|      }
608|      setConnectionPhase('switching');
609|      let library;
610|      try {
611|        library = await loadOfflineLibrary();
612|      } catch {
613|        setConnectionPhase('no-copy');
614|        throw onlineError;
615|      }
616|      if (library === null) {
617|        setConnectionPhase('no-copy');
618|        throw onlineError;
619|      }
620|      setMode('offline');
621|      if (options.state !== undefined) options.state.lastFallbackAt = new Date().toISOString();
622|      setConnectionPhase(null);
623|      return offlineCall(library);
624|    }
625|  }
