634|    if (unsupported || Object.keys(input).length === 0) throw transportError;
635|    const active = await readActiveSnapshot(store);
636|    const original = active?.snapshot.payload.entries.find((entry) => entry.id === entryId);
637|    if (active === null || original?.syncUid === undefined || original.syncVersion === undefined) {
638|      throw transportError;
639|    }
640|
641|    const operations = await store.list();
642|    const parsed = parsedEntryOperations(operations);
643|    const earlier = parsed
644|      .filter(isEntryUpdateOperation)
645|      .filter((operation) => operation.entityUid === original.syncUid);
646|    const versionAdvances = parsed.filter((operation) => (
647|      operation.entityUid === original.syncUid && advancesEntryVersion(operation)
648|    )).length;
649|    const current = earlier.reduce((entry, operation) => applyEntryPatch(entry, operation.payload), original);
650|    const payload = {
651|      ...(input.title !== undefined ? { title: input.title } : {}),
652|      ...(input.uploadDate !== undefined ? { uploadDate: input.uploadDate } : {}),
653|      ...(input.pageCount !== undefined ? { pageCount: input.pageCount } : {}),
654|    };
655|    const baseValues = {
656|      ...(input.title !== undefined ? { title: current.title } : {}),
657|      ...(input.uploadDate !== undefined ? { uploadDate: current.uploadDate } : {}),
658|      ...(input.pageCount !== undefined ? { pageCount: current.pageCount } : {}),
659|    };
660|    const operation = createPendingSyncOperation({
661|      clientId,
662|      libraryId: active.snapshot.header.libraryId,
663|      syncEpoch: active.snapshot.header.syncEpoch,
664|      entityKind: 'entry',
665|      entityUid: original.syncUid,
666|      operationKind: 'entry.update',
667|      baseVersion: original.syncVersion + versionAdvances,
668|      baseValues,
669|      payload,
670|    }, { randomUUID });
671|    const normalized = {
672|      ...operation,
673|      ...transportOperation(operation),
674|    } as PendingSyncOperation;
675|    await store.enqueue(normalized);
