946|    const type = input.type.trim();
947|    if (title.length === 0 || type.length === 0) throw new Error('Title and Gallery are required');
948|    if (!active.snapshot.payload.entries.some((entry) => entry.type === type)) {
949|      throw new Error('Offline creation can only use an existing Gallery from this offline copy');
950|    }
951|    const files = [
952|      ...(input.coverFile === null ? [] : [{ kind: 'cover' as const, file: input.coverFile }]),
953|      ...(input.previewFile === null ? [] : [{ kind: 'preview' as const, file: input.previewFile }]),
954|    ];
