971|    const operation = createPendingSyncOperation({
972|      clientId,
973|      libraryId: active.snapshot.header.libraryId,
974|      syncEpoch: active.snapshot.header.syncEpoch,
975|      entityKind: 'entry',
976|      entityUid,
977|      operationKind: 'entry.create',
978|      baseVersion: 0,
979|      baseValues: {},
980|      payload: {
981|        title,
982|        type,
983|        uploadDate: input.uploadDate,
984|        pageCount: input.pageCount,
985|        ratings: [...input.ratings].sort((left, right) => left.slotId - right.slotId),
986|        viewLater: input.viewLater,
