1001|      media.push({
1002|        uploadId: randomUUID(),
1003|        libraryId: normalized.libraryId,
1004|        syncEpoch: normalized.syncEpoch,
1005|        entryUid: entityUid,
1006|        kind,
1007|        ordinal: 0,
1008|        mimeType: file.type as StagedMediaUpload['mimeType'],
