1044|  async function replayPendingOperations(): Promise<void> {
1045|    if (replayPromise !== null) return replayPromise;
1046|    replayPromise = (async () => {
1047|      if (!hasOutbox(store) || online.replaySyncOperation === undefined) return;
1048|      const operations = await store.list();
1049|      const mediaBeforeReplay = hasMediaOutbox(store) ? await store.listMedia() : [];
1050|      await setReplayStateFromStore();
1051|      if (operations.length === 0 && mediaBeforeReplay.length === 0) return;
1052|      const activeBeforeReplay = await readActiveSnapshot(store);
1053|      const appliedOperations: SyncReplayOperation[] = [];
1054|      const appliedMedia: StagedMediaUpload[] = [];
1055|      let maxAppliedServerSeq = -1;
1056|      const blockedEntities = new Set<string>();
1057|      let replayError: string | null = null;
1058|      let attemptedOpId: string | null = null;
1059|      let attemptedUploadId: string | null = null;
1060|      try {
1061|        for (const stored of operations) {
1062|          const entityKey = `${stored.entityKind}:${stored.entityUid}`;
1063|          if (stored.status !== 'pending') {
1064|            blockedEntities.add(entityKey);
1065|            replayError ??= stored.lastError;
1066|            continue;
1067|          }
1068|          if (blockedEntities.has(entityKey)) continue;
1069|          let operation: SyncReplayOperation;
1070|          try {
1071|            operation = transportOperation(stored);
1072|          } catch {
1073|            // An envelope this build can no longer express (for example one queued
1074|            // by another app version) must neither be sent nor silently dropped,
1075|            // and it must not stop unrelated Entries from syncing.
1076|            replayError = 'Invalid offline operation: this version cannot send it';
1077|            await store.update(stored.opId, { status: 'failed', lastError: replayError });
1078|            blockedEntities.add(entityKey);
1079|            continue;
1080|          }
1081|          attemptedOpId = stored.opId;
1082|          await store.update(stored.opId, {
1083|            lastAttemptAt: new Date().toISOString(),
1084|            lastError: null,
1085|          });
1086|          const result = await online.replaySyncOperation(operation);
1087|          if (result.status === 'applied') {
1088|            appliedOperations.push(operation);
1089|            maxAppliedServerSeq = Math.max(maxAppliedServerSeq, result.serverSeq);
1090|            attemptedOpId = null;
1091|            continue;
1092|          }
1093|          if (result.status === 'conflict') {
1094|            replayError = 'An offline edit conflicts with a newer server value';
1095|            await store.update(stored.opId, { status: 'conflict', lastError: replayError });
1096|          } else if (result.status === 'resnapshot-required') {
1097|            replayError = 'The library changed and the offline edit needs review';
1098|            await store.update(stored.opId, { status: 'conflict', lastError: replayError });
1099|          } else {
1100|            replayError = result.detail;
1101|            await store.update(stored.opId, { status: 'failed', lastError: replayError });
1102|          }
1103|          blockedEntities.add(entityKey);
1104|          attemptedOpId = null;
1105|        }
1106|
1107|        if (hasMediaOutbox(store) && online.uploadSyncMedia !== undefined) {
1108|          const readyEntryUids = new Set(
1109|            activeBeforeReplay?.snapshot.payload.entries.map((entry) => entry.syncUid) ?? [],
1110|          );
1111|          for (const operation of appliedOperations) {
1112|            if (operation.operationKind === 'entry.create') readyEntryUids.add(operation.entityUid);
1113|          }
1114|          for (const upload of mediaBeforeReplay) {
1115|            if (upload.status !== 'pending' || !readyEntryUids.has(upload.entryUid)) continue;
1116|            attemptedUploadId = upload.uploadId;
1117|            await store.updateMedia(upload.uploadId, {
1118|              lastAttemptAt: new Date().toISOString(),
1119|              lastError: null,
1120|            });
1121|            try {
1122|              const result = await online.uploadSyncMedia(upload.uploadId, {
1123|                libraryId: upload.libraryId,
1124|                syncEpoch: upload.syncEpoch,
1125|                entryUid: upload.entryUid,
1126|                kind: upload.kind,
1127|                ordinal: upload.ordinal,
1128|                mimeType: upload.mimeType,
1129|                byteLength: upload.byteLength,
1130|                sha256: upload.sha256,
1131|              }, upload.blob);
1132|              appliedMedia.push(upload);
1133|              maxAppliedServerSeq = Math.max(maxAppliedServerSeq, result.serverSeq);
1134|              attemptedUploadId = null;
1135|            } catch (cause) {
1136|              if (cause instanceof ApiError && [400, 404, 409].includes(cause.status)) {
1137|                replayError = cause.message;
1138|                await store.updateMedia(upload.uploadId, { status: 'failed', lastError: replayError });
1139|                attemptedUploadId = null;
1140|                continue;
1141|              }
1142|              throw cause;
1143|            }
1144|          }
1145|        }
1146|
1147|        if (appliedOperations.length > 0 || appliedMedia.length > 0) {
1148|          const first = appliedOperations[0];
1149|          const snapshot = await online.fetchSyncSnapshot();
1150|          if (snapshot.header.changeSeq === undefined || snapshot.header.changeSeq < maxAppliedServerSeq) {
1151|            throw new Error(
1152|              `Snapshot refresh failed: change sequence ${String(snapshot.header.changeSeq)} does not cover replay ${maxAppliedServerSeq}`,
1153|            );
1154|          }
1155|          const currentLibraryId = first?.libraryId
1156|            ?? activeBeforeReplay?.snapshot.header.libraryId;
1157|          const currentSyncEpoch = first?.syncEpoch
1158|            ?? activeBeforeReplay?.snapshot.header.syncEpoch;
1159|          if (currentLibraryId === undefined || currentSyncEpoch === undefined) {
1160|            throw new Error('Snapshot refresh failed: no paired offline library identity');
1161|          }
1162|          const applied = await applySnapshot(snapshot, {
1163|            store,
1164|            currentLibraryId,
1165|            currentSyncEpoch,
1166|            ...(activeBeforeReplay === null
1167|              ? {}
1168|              : { currentSnapshotSeq: activeBeforeReplay.snapshot.header.snapshotSeq }),
1169|          });
1170|          if (!applied.ok) throw new Error(`Snapshot refresh failed: ${applied.failure.reason}`);
1171|          for (const operation of appliedOperations) await store.remove(operation.opId);
1172|          if (hasMediaOutbox(store)) {
1173|            for (const upload of appliedMedia) await store.removeMedia(upload.uploadId);
1174|          }
1175|          invalidateOfflineLibrary();
1176|        }
1177|      } catch (cause) {
1178|        replayError = cause instanceof Error ? cause.message : String(cause);
1179|        if (attemptedOpId !== null) {
1180|          await store.update(attemptedOpId, { status: 'pending', lastError: replayError });
1181|        }
1182|        if (attemptedUploadId !== null && hasMediaOutbox(store)) {
1183|          await store.updateMedia(attemptedUploadId, { status: 'pending', lastError: replayError });
1184|        }
1185|      } finally {
1186|        await setReplayStateFromStore(replayError);
1187|      }
1188|    })().finally(() => {
1189|      replayPromise = null;
1190|    });
1191|    return replayPromise;
1192|  }
