1199|      if (operation.status !== 'conflict' && operation.status !== 'failed') return;
1200|      if (!firstBlockedIndexByEntity.has(operation.entityUid)) {
1201|        firstBlockedIndexByEntity.set(operation.entityUid, index);
1202|      }
