912|  async function enqueueEntryViewLater(
913|    entryId: number,
914|    desiredPresent: boolean,
915|    transportError?: unknown,
916|  ): Promise<ViewLaterState> {
917|    if (transportError !== undefined && !isOfflineTransportError(transportError)) throw transportError;
918|    if (!hasOutbox(store)) throw transportError ?? new Error('Offline View later storage is unavailable');
919|    if (await store.readMeta(ENTRY_VIEW_LATER_CAPABILITY_KEY) !== '1') {
920|      throw new Error('This offline copy has not enabled offline View later; update it while online');
921|    }
922|    const active = await readActiveSnapshot(store);
923|    const original = active?.snapshot.payload.entries.find((entry) => entry.id === entryId);
924|    if (active === null || original?.syncUid === undefined || original.syncVersion === undefined) {
925|      throw transportError ?? new Error('Entry is unavailable in the offline copy');
926|    }
927|
928|    const operations = await store.list();
929|    const parsed = parsedEntryOperations(operations);
930|    const projectedBefore = snapshotWithOverlays(active.snapshot, operations);
931|    const present = projectedBefore.payload.viewLaterEntries
932|      .some((membership) => membership.subjectId === entryId);
933|    if (present === desiredPresent) return viewLaterStateFromSnapshot(projectedBefore);
934|    const versionAdvances = parsed.filter((operation) => (
935|      operation.entityUid === original.syncUid && advancesEntryVersion(operation)
936|    )).length;
937|    const operation = createPendingSyncOperation({
938|      clientId,
939|      libraryId: active.snapshot.header.libraryId,
940|      syncEpoch: active.snapshot.header.syncEpoch,
941|      entityKind: 'entry',
942|      entityUid: original.syncUid,
943|      operationKind: 'entry.view-later.set',
944|      baseVersion: original.syncVersion + versionAdvances,
945|      baseValues: { present },
946|      payload: { present: desiredPresent },
947|    }, { randomUUID });
948|    const normalized = {
949|      ...operation,
950|      ...transportOperation(operation),
951|    } as PendingSyncOperation;
952|    await store.enqueue(normalized);
953|    const pending = [...operations, normalized];
954|    setReplayStateFromOperations(pending);
955|    invalidateOfflineLibrary();
956|    setMode('offline');
957|    return viewLaterStateFromSnapshot(snapshotWithOverlays(active.snapshot, pending));
