117|      new Promise<never>((_, reject) => {
118|        timeout = setTimeout(() => reject(new OfflineReadTimeout()), timeoutMs);
119|      }),
120|    ]);
121|  } finally {
122|    if (timeout !== undefined) clearTimeout(timeout);
