1694|    if (!hasMediaOutbox(store)) throw new Error('Offline create storage is unavailable');
1695|    const active = await readActiveSnapshot(store);
1696|    if (active === null) throw new Error('Download an offline copy before creating Entries offline');
1697|    if (await store.readMeta(ENTRY_CREATE_CAPABILITY_KEY) !== '1') {
1698|      throw new Error('This offline copy has not enabled offline Entry creation; update it while online');
1699|    }
1700|    const title = input.title.trim();
1701|    const type = input.type.trim();
1702|    if (title.length === 0 || type.length === 0) throw new Error('Title and Gallery are required');
1703|    if (!active.snapshot.payload.entries.some((entry) => entry.type === type)) {
1704|      throw new Error('Offline creation can only use an existing Gallery from this offline copy');
1705|    }
1706|    const files = [
1707|      ...(input.coverFile === null ? [] : [{ kind: 'cover' as const, file: input.coverFile }]),
1708|      ...(input.previewFile === null ? [] : [{ kind: 'preview' as const, file: input.previewFile }]),
1709|    ];
1710|    if (files.length > 0 && await store.readMeta(MEDIA_UPLOAD_CAPABILITY_KEY) !== '1') {
1711|      throw new Error('This offline copy has not enabled staged media upload; update it while online');
1712|    }
1713|    const requiredBytes = files.reduce((total, { file }) => total + file.size, 0);
1714|    try {
1715|      const estimate = await globalThis.navigator?.storage?.estimate();
1716|      if (estimate?.quota !== undefined && estimate.usage !== undefined
1717|        && estimate.quota - estimate.usage < Math.ceil(requiredBytes * 1.1)) {
1718|        throw new Error('Not enough browser storage to stage these offline images');
1719|      }
1720|    } catch (cause) {
1721|      if (cause instanceof Error && cause.message.startsWith('Not enough browser storage')) throw cause;
1722|      // Storage estimation is advisory and is absent on some PWA engines. The
1723|      // multi-store IndexedDB transaction remains the durability boundary.
1724|    }
