1726|    const parsed = parsedEntryOperations(operations);
1727|    const projected = snapshotWithOverlays(active.snapshot, operations);
1728|    const useStableRatingUids = await store.readMeta(RATING_LAYOUT_CAPABILITY_KEY) === '1';
