1731|      const slot = projected.payload.ratingSlots.find((candidate) => (
1732|        candidate.id === rating.slotId && candidate.subjectKind === 'entry' && candidate.entryType === type
1733|      ));
1734|      if (slot === undefined) throw new Error('Rating slot is unavailable in the offline copy');
1735|      if (useStableRatingUids) {
