1746|    const entityUid = randomUUID();
1747|    const operation = createPendingSyncOperation({
1748|      clientId,
1749|      libraryId: active.snapshot.header.libraryId,
1750|      syncEpoch: active.snapshot.header.syncEpoch,
1751|      entityKind: 'entry',
1752|      entityUid,
1753|      operationKind: 'entry.create',
1754|      baseVersion: 0,
1755|      baseValues: {},
1756|      payload: {
1757|        title,
1758|        type,
1759|        uploadDate: input.uploadDate,
1760|        pageCount: input.pageCount,
1761|        ratings: ratings,
1762|        viewLater: input.viewLater,
