134|async function boundedRead<T>(read: () => Promise<T>, timeoutMs: number): Promise<T> {
135|  let timeout: ReturnType<typeof setTimeout> | undefined;
136|  try {
137|    return await Promise.race([
138|      read(),
139|      new Promise<never>((_, reject) => {
140|        timeout = setTimeout(() => reject(new OfflineReadTimeout()), timeoutMs);
141|      }),
142|    ]);
143|  } finally {
144|    if (timeout !== undefined) clearTimeout(timeout);
145|  }
