266|      && alias.normalizedAlias === normalized)
267|    .map((alias) => alias.normalizedCanonical));
268|  const candidates = exact.length > 0 ? exact : snapshot.payload.producers.filter((producer) => (
269|    canonicalNames.has(normalizeTag(producer.name))
