280|  const visited = new Set<string>();
281|  while (!visited.has(normalizeTag(name))) {
282|    const normalized = normalizeTag(name);
283|    visited.add(normalized);
284|    const alias = (snapshot.payload.taxonomyAliases ?? []).find((row) => (
285|      row.vocabulary === 'producer' && row.partition === 'authors'
286|      && row.normalizedAlias === normalized && row.normalizedCanonical !== ''
287|    ));
288|    if (alias === undefined) break;
289|    name = alias.canonicalName.normalize('NFKC').trim().replace(/\s+/gu, ' ');
290|  }
